const stages=[{en:'Understand',name:'구매조건 설정',pose:'welcome',desc:'희망 지역·예산을 확인하고 분석 조건과 공유 프로필을 구분해요.',items:['login','conditions','profile']},{en:'Find',name:'청약 기회 탐색',pose:'loading',desc:'조건 충족·확인 필요를 나누고 한 공고·한 주택형을 골라요.',items:['loading','results','selected']},{en:'Verify',name:'가격·자금 검증',pose:'thinking',desc:'공급면적과 거래 종류를 맞춰 비교하고 납부 시점의 부족액을 봐요.',items:['comparison','funding','held','empty','error']},{en:'Explain',name:'근거·주의사항 설명',pose:'complete',desc:'출처·적용 시점과 미확인 내용을 보고서와 다음 행동으로 정리해요.',items:['evidence','legal','commute','news','report','library']},{en:'Alert',name:'청약 기회 알림',pose:'welcome',desc:'다시 탐색·검증하고 중복을 확인한 뒤 알리는 확장 구상이에요.',items:['alert'],future:true}];
const initial=new URLSearchParams(location.search).get('view');
const initialCondition=()=>({regions:['11215','11200'],budget:800e6,areaMin:'',areaMax:'',unit:'㎡',moveStart:'',moveEnd:'',closed:false});
const state={view:views[initial]?initial:'welcome',auth:!!initial&&!['welcome','login'].includes(initial),panel:innerWidth>1180,draft:'',condition:initialCondition(),noticeId:'A',model:'84A',room:'range',selected:!!initial&&['comparison','funding','evidence','legal','commute','news','report','held','empty','error'].includes(initial),trade:'매매',profileDecision:null,profileVersion:1,shared:{region:'서울특별시 광진구',budget:700e6,destination:'미등록'},funds:{cash:50e6,extra:4e6,date:'2026-12-10',certainty:'예상',include:true},destination:'',routes:false,pdfState:'ready',saved:null,history:[],showHistory:false,loadingNext:'results',compareRange:5,compareStart:'2025-11-25',compareEnd:'2026-11-24',newsOpen:false};
const notice=()=>catalog.find(n=>n.id===state.noticeId)||catalog[0];
const model=()=>notice().models[state.model]||Object.values(notice().models)[0];
const confirmed=()=>model().rooms.filter(r=>r.option!==null);
const prices=()=>confirmed().map(r=>r.body+r.option);
const regionNames=c=>c.regions.map(id=>regions.find(r=>r.id===id)?.name).join(' · ');
function priceLabel(){const r=model().rooms.find(r=>r.id===state.room);if(r)return r.option===null?'필수 옵션 미확인':money(r.body+r.option);const p=prices();return p.length?Math.min(...p)===Math.max(...p)?money(p[0]):`${money(Math.min(...p))}–${money(Math.max(...p))}`:'가격 확인 필요';}
function currentPrice(){const r=model().rooms.find(r=>r.id===state.room);return r&&r.option!==null?r.body+r.option:null;}
function matching(){const fit=[],held=[],outside=[];for(const n of catalog){const c=state.condition;if(!c.regions.includes(n.region)||(!c.closed&&n.status==='접수 종료'))continue;let yes=false,unknown=false;for(const m of Object.values(n.models)){const scale=c.unit==='평'?3.305785:1;if((c.areaMin&&m.supply<Number(c.areaMin)*scale)||(c.areaMax&&m.supply>Number(c.areaMax)*scale)||(c.moveStart&&n.move[1]<c.moveStart)||(c.moveEnd&&n.move[0]>c.moveEnd))continue;for(const r of m.rooms){if(r.body>c.budget)continue;if(r.option===null)unknown=true;else if(r.body+r.option<=c.budget)yes=true;}}if(yes)fit.push(n);else if(unknown)held.push(n);else outside.push(n);}const rank={'접수 중':0,'접수 예정':1,'접수 종료':2};fit.sort((a,b)=>rank[a.status]-rank[b.status]||(a.status==='접수 중'?a.end.localeCompare(b.end):a.start.localeCompare(b.start)));return{fit,held,outside};}
function setView(v,{allow=false}={}){if(!views[v])return;if(!state.auth&&!['welcome','login','flow','alert'].includes(v)&&!allow){state.afterLogin=v;v='login';}if(v!==state.view&&state.view!=='welcome')state.history.push(state.view);if(state.view==='news'&&v!=='news')state.newsOpen=false;state.view=v;state.draft='';state.showHistory=false;history.replaceState(null,'',`${location.pathname}?view=${v}`);render();if(v==='loading'){clearTimeout(state.timer);state.timer=setTimeout(()=>{if(state.view==='loading')setView(state.loadingNext);},1800);}}
function conditionSummary(c=state.condition){const scale=c.unit==='㎡'?1/3.305785:3.305785;return facts([['희망 지역',regionNames(c)||'입력 필요'],['구매 가격 상한',money(c.budget)],['공급면적',c.areaMin||c.areaMax?`${c.areaMin||'—'}–${c.areaMax||'—'}${c.unit}<br>(${c.areaMin?(Number(c.areaMin)*scale).toFixed(1):'—'}–${c.areaMax?(Number(c.areaMax)*scale).toFixed(1):'—'}${c.unit==='㎡'?'평':'㎡'})`:'조건 적용 안 함'],['입주 시기',c.moveStart||c.moveEnd?`${c.moveStart||'—'}–${c.moveEnd||'—'}`:'조건 적용 안 함'],['접수 상태',c.closed?'접수 중 · 예정 · 종료':'접수 중 · 예정']]);}
function conditionEditor(){const c=state.condition;return `<form id="condition-form"><fieldset><legend>희망 지역 <em>필수 · 여러 곳 선택</em></legend><div class="region-options">${regions.map(r=>`<label class="check-option"><input type="checkbox" name="region" value="${r.id}" ${c.regions.includes(r.id)?'checked':''}><span>${r.name}<small>지역코드 ${r.id}</small></span></label>`).join('')}</div></fieldset>${field('구매 가격 상한 · 필수',`<div class="input-suffix"><input name="budget" aria-label="최대 예산 원" type="number" min="1" max="100000000000" step="1" required value="${c.budget}"><span>원</span></div>`,'분양가 + 필수 옵션과 비교해요. 보유 현금이나 대출 한도가 아니에요.')}<details class="optional-fields" ${c.areaMin||c.areaMax||c.moveStart||c.moveEnd?'open':''}><summary>면적과 입주 시기 더하기 <span>선택</span></summary><div class="form-row">${field('공급면적 최소',`<input name="areaMin" type="number" min="0.01" step="any" value="${c.areaMin}" placeholder="최소">`)}${field('최대',`<input name="areaMax" type="number" min="0.01" step="any" value="${c.areaMax}" placeholder="최대">`)}${field('단위',`<select name="unit"><option ${c.unit==='㎡'?'selected':''}>㎡</option><option ${c.unit==='평'?'selected':''}>평</option></select>`)}</div><p class="micro">전용면적과 구분하고 ㎡·평을 함께 표시해요.</p><div class="form-row">${field('입주 시작월',`<input name="moveStart" type="month" value="${c.moveStart}">`)}${field('입주 종료월',`<input name="moveEnd" type="month" value="${c.moveEnd}">`)}</div><p class="micro">입주 예정 기간과 겹치면 포함해요. 비워두면 선택 조건을 적용하지 않아요.</p></details><label class="checkbox-line"><input type="checkbox" name="closed" ${c.closed?'checked':''}> 접수 종료 공고도 포함</label><p id="condition-error" class="form-error" role="alert"></p><div class="actions"><span class="micro">이번 검색에만 적용해요</span><button class="primary" type="submit">조건 확인하기 ${icon('right')}</button></div></form>`;}
function auroraWelcome(){return `<div class="aurora-welcome"><span class="ai-intro-badge"><i aria-hidden="true"></i>AI와 함께 찾는 나의 첫 집</span><div class="intelligence-visual"><div class="intelligence-halo" aria-hidden="true"></div><div class="intelligence-ring" aria-hidden="true"></div><span class="orbit-label one" aria-hidden="true">${icon('search')}청약 공고</span><span class="orbit-label two" aria-hidden="true">${icon('chart')}가격 근거</span><span class="orbit-label three" aria-hidden="true">${icon('wallet')}자금 계획</span>${mascot('welcome','aurora-hero-mascot')}</div><h1>조건을 이야기하면,<br><span>내 집의 가능성이 보여요.</span></h1><p>청약 공고부터 가격, 자금, 출퇴근까지.<br>AI와 대화하며 나에게 맞는 기회를 하나씩 알아보세요.</p></div>`;}
function auroraFollowup(){return `<div class="aurora-home-followup"><div class="prompt-section-heading">이렇게 대화를 시작해 보세요 <span>START WITH A QUESTION</span></div><div class="ai-prompts">${[['search','내 조건에 맞는<br>청약을 찾고 싶어요','광진구나 성동구에서 8억 이내의 청약을 찾고 있어요.'],['chart','눈여겨본 공고,<br>가격이 궁금해요','눈여겨본 공고의 주택형과 가격을 검토하고 싶어요.'],['wallet','계약금과 잔금,<br>미리 준비하고 싶어요','선택한 공고의 자금과 납부 일정을 검토하고 싶어요.']].map(([i,label,prompt])=>btn('prompt',`${icon(i)}<strong>${label}</strong><span>질문해 보기 ↗</span>`,'ai-prompt','',`data-prompt="${prompt}"`)).join('')}</div><div class="ai-understanding-path"><span><b>01</b>질문을 조건으로</span><i>→</i><span><b>02</b>조건에 맞는 공고로</span><i>→</i><span><b>03</b>근거 있는 검토로</span></div></div>`;}
function welcome(){if(isAurora)return auroraWelcome();return `<div class="welcome"><div class="welcome-visual">${mascot('welcome','hero-mascot')}</div><span class="eyebrow">YOUR HOME, ONE CONVERSATION CLOSER</span><h1>내 집 마련의 막막함을,<br><span>함께 알아가는 대화로.</span></h1><p>원하는 지역과 예산부터 알려주세요.<br>청약 공고부터 가격, 자금, 출퇴근까지 하나씩 짚어드릴게요.</p><div class="welcome-actions">${go('conditions','나에게 맞는 공고 찾기','primary','search')}${go('selected','눈여겨본 공고 검토','secondary','file')}</div><div class="home-journey"><div><b>01</b><strong>조건을 정하고</strong><span>지역 · 예산 · 원하는 크기</span></div><i>→</i><div><b>02</b><strong>기회를 찾아</strong><span>충족 공고와 확인 필요 구분</span></div><i>→</i><div><b>03</b><strong>근거로 검토해요</strong><span>가격 · 자금 · 생활 조건</span></div></div><p class="trust-line">${icon('shield')}확인된 사실과 아직 모르는 내용을 나눠 안내해요.</p></div>`;}
function login(){return `<div class="auth-layout">${mascot('welcome','state-mascot')}<h2>로그인하고, 내 검토를 이어가세요</h2><p>대화와 확인한 조건, 보고서를 내 계정에서 관리해요.</p><div class="auth-card">${[['chat','여러 대화를 나눠서 검토'],['file','같은 결과로 보고서 다시 열기'],['shield','확인한 조건만 프로필에 반영']].map(([i,s])=>`<div class="auth-benefit">${icon(i)}${s}</div>`).join('')}${btn('demo-login','예시 계정으로 화면 살펴보기','primary','right')}<a class="secondary" href="/#home">실제 서비스 로그인 열기 ↗</a><p class="micro">시안에서는 개인정보를 입력받지 않아요.<br>예시 계정은 실제 로그인·저장 기능이 아닙니다.</p></div></div>`;}
function resultCard(n,held=false){const c=state.condition,scale=c.unit==='평'?3.305785:1;const available=Object.entries(n.models).filter(([,m])=>(!c.areaMin||m.supply>=Number(c.areaMin)*scale)&&(!c.areaMax||m.supply<=Number(c.areaMax)*scale)).flatMap(([k,m])=>m.rooms.filter(r=>r.option!==null&&r.body+r.option<=c.budget).map(r=>({k,m,r})));const a=available[0];return `<article class="notice-card"><div class="card-top"><div>${badge(n.status,n.status==='접수 중'?'purple':'')} ${badge(n.type)}</div><span class="micro">${n.status==='접수 예정'?n.start+' 시작':n.end+' 마감'}</span></div><h3>합성 ${n.name}</h3><p>${regions.find(r=>r.id===n.region)?.name} · 공고 990000004${n.id.charCodeAt(0)-65}</p>${held?note('필수 옵션 금액을 확인하지 못해 예산 판정을 보류했어요.','warning'):`<div class="notice-price"><strong>${money(a.r.body+a.r.option)}</strong><span>분양가 + 필수 옵션</span></div><p class="micro">${a.k} · ${a.r.id}<br>공급 ${a.m.supply}㎡ (${(a.m.supply/3.305785).toFixed(1)}평) · 전용 ${a.m.private}㎡<br>입주 예정 ${n.move.join('–')}</p>${n.id==='A'?'<div class="subtle-hold">다른 호실 1개는 필수 옵션 확인 필요</div>':''}`}<div class="actions"><span class="micro">공고일 2026.11.20 · 합성</span>${btn('select-notice',held?'미확인 항목 보기':'공고와 주택형 확인',held?'secondary':'primary','right',`data-id="${n.id}"`)}</div></article>`;}
function results(){const r=matching();return `<p class="lead"><strong>조건 충족 ${r.fit.length}개</strong>와 <strong>확인 필요 ${r.held.length}개</strong>를 나눠 살펴보세요.</p><div class="result-toolbar"><span>접수 중 마감일순 → 예정 시작일순</span>${go('conditions','조건 수정','text-button','settings')}</div><section class="result-section"><h3>조건을 충족한 공고 <span>${r.fit.length}</span></h3>${r.fit.map(n=>resultCard(n)).join('')||note('현재 예시 자료에서 충족 공고를 찾지 못했어요. 확인 필요 목록도 함께 확인해 주세요.')}</section><section class="result-section"><h3>확인이 더 필요한 공고 <span>${r.held.length}</span></h3><p class="micro">충족 공고 수에 합산하지 않고 한 공고는 한 번만 표시해요.</p>${r.held.map(n=>resultCard(n,true)).join('')||'<p class="micro">이 예시 범위에는 확인 필요 공고가 없어요.</p>'}</section>${note('4개 합성 공고에 입력 조건을 적용한 예시예요. 실제 검색 결과가 아니며, 접수 상태가 개인의 신청 자격을 뜻하지 않아요.')}<details class="quiet-details"><summary>확인된 조건 위반으로 제외 ${r.outside.length}개</summary><p>${r.outside.map(n=>'합성 '+n.name).join(' · ')||'없음'}</p></details>`;}
function selected(){const n=notice(),m=model();return `<div class="notice-heading"><div>${badge(n.status,'purple')} ${badge(n.type)}</div><h2>합성 ${n.name}</h2><p>${regions.find(r=>r.id===n.region)?.name} · 공고번호 990000004${n.id.charCodeAt(0)-65}</p></div><section class="surface"><div class="section-title"><h3>공식 문서와 점검 상태</h3><select id="pdf-state" aria-label="문서 상태 예시">${[['ready','자동 확보 예시'],['failed','확보 실패 예시'],['conflict','다른 회차 예시']].map(([k,s])=>`<option value="${k}" ${state.pdfState===k?'selected':''}>${s}</option>`).join('')}</select></div>${state.pdfState==='ready'?`<div class="verified-line">${icon('check')}같은 공고·회차 PDF 확보 · 원문·단위 점검 상태 예시</div>${source('공식 PDF · synthetic-v1 · 3·7·8쪽')}`:state.pdfState==='failed'?`${note('자동 확보 실패 · 기본 공고 정보는 유지해요. 가격·면적 원문은 보완 후 점검해요.','warning')}${btn('upload','같은 회차 PDF로 보완','secondary','file')}`:note('문서와 선택 공고의 회차가 달라요. 값을 병합하지 않고 가격·면적 판정을 보류해요.','warning')}</section><section class="surface"><h3>주택형 하나를 선택하세요</h3><div class="model-options" role="group" aria-label="주택형 선택">${Object.entries(n.models).map(([k,v])=>`<button class="model-option ${k===state.model?'active':''}" data-action="model" data-model="${k}" aria-pressed="${k===state.model}"><strong>${k}</strong><span>공급 ${v.supply}㎡ · ${(v.supply/3.305785).toFixed(1)}평</span><small>전용 ${v.private}㎡</small></button>`).join('')}</div>${roomSelect('room-select','가격 비교에 사용할 호실')}<div class="price-focus"><small>${state.room==='range'?'확인된 호실의 소계 범위':'선택 호실의 소계'}</small><strong>${state.pdfState==='ready'?priceLabel():'원문 확인 후 제공'}</strong><span>분양가 + 필수 옵션 · 세금·금융비용 별도</span></div>${source()}<p class="micro">확인 ${confirmed().length} / 전체 ${m.rooms.length}호실. 미확인 호실을 0원으로 채우거나 전체 가격 범위로 일반화하지 않아요.</p><div class="actions"><span class="micro">한 공고 · 한 주택형씩 분석</span>${btn('start-compare','이 주택형으로 비교','primary','chart')}</div></section>`;}
function roomSelect(id,label){return field(label,`<select id="${id}"><option value="range" ${state.room==='range'?'selected':''}>${id==='funding-room'?'특정 호실 선택 필요':'확인된 호실 가격 범위로 보기'}</option>${model().rooms.map(r=>`<option value="${r.id}" ${state.room===r.id?'selected':''}>${r.id} · ${r.option===null?'필수 옵션 미확인':money(r.body+r.option)}</option>`).join('')}</select>`);}
function comparison(){if(!state.selected)return `<section class="surface"><h3>먼저 공고와 주택형을 선택해 주세요</h3><p class="lead">한 공고·한 주택형의 근거로 비교해요.</p>${go('selected','공고·주택형 선택','primary')}</section>`;if(state.pdfState!=='ready'||!prices().length||(state.room!=='range'&&currentPrice()===null))return statusView('held');if(state.comparisonNeedsReview)return `<section class="state-view">${mascot('held','state-mascot')}<h2>변경한 조건의 비교 근거가 필요해요</h2><p>새 조건을 적용했고 이전 통계는 숨겼어요. 현재 합성 자료는 새 범위의 수집·선정을 검증하지 않았습니다.</p>${facts([['공급면적',`±${state.compareRange}%`],['계약일',`${state.compareStart}–${state.compareEnd}`]])}${go('evidence','근거 보완 위치 보기','primary')}</section>`;const m=model(),near=m.supply+.1;return `<div class="selection-banner">${icon('home')}<div><strong>합성 ${notice().name} · ${state.model}</strong><small>공급 ${m.supply}㎡ · 전용 ${m.private}㎡ · ${state.room==='range'?'확인된 호실 범위':state.room}</small></div>${go('selected','선택 변경','text-button')}</div><details class="surface comparison-settings"><summary><span>같은 법정동 · 공급면적 ±${state.compareRange}%</span><small>${state.compareStart}–${state.compareEnd} · 조건 펼치기</small></summary><div class="section-title"><h3>적용한 비교 범위</h3>${btn('edit-comparison','조건 변경','text-button','settings')}</div>${facts([['지역','같은 법정동 · 합성 소재지 배정 예시'],['공급면적',`${m.supply}㎡ ±${state.compareRange}% · ${(m.supply*(1-state.compareRange/100)).toFixed(2)}–${(m.supply*(1+state.compareRange/100)).toFixed(2)}㎡`],['계약일',`${state.compareStart}–${state.compareEnd}`],['수집 기준','2026.11.24 · 진행 중인 당월 포함']])}<p class="micro">같은 동의 고유 주변 2단지 예시. 종류 전체 최대 5단지, 최근접 공급면적 → 직선거리순으로 선정해요.</p></details><section class="surface"><div class="trade-tabs" role="tablist" aria-label="거래 종류">${['매매','분양권','입주권'].map(t=>`<button role="tab" aria-selected="${state.trade===t}" class="${state.trade===t?'active':''}" data-action="trade" data-trade="${t}">${t}</button>`).join('')}</div>${state.trade==='입주권'?`${note('입주권 조회 실패 · 매매·분양권 결과는 유지해요. 정상 0건으로 처리하지 않아요.','warning')}${go('error','실패 상태 보기')}`:state.trade==='분양권'?`${badge('정상 0건')}<p class="lead">이 지역·기간·면적의 분양권 유효 거래는 0건인 예시예요.</p><p class="micro">매매 후보가 있으므로 공통 비교 지역은 유지해요.</p>`:`<div class="comparison-head"><small>선택 공고 · ${state.room==='range'?'확인된 호실 범위':'선택 호실 소계'}</small><strong>${priceLabel()}</strong><span>분양가 + 필수 옵션 · 주변 매매와 금액 의미가 달라요.</span></div><div class="table-scroll"><table><caption>선정 공급면적별 매매 통계 · 해제 거래 제외</caption><thead><tr><th>주변 단지</th><th>최소</th><th>중위</th><th>최대</th><th>유효 건수</th></tr></thead><tbody><tr><th>합성 비교 A<small>공급 ${near.toFixed(1)}㎡ · 거리 320m</small></th><td>5.15억</td><td><b>5.15억</b></td><td>5.15억</td><td>1건 ${badge('적은 표본','warning')}</td></tr><tr><th>합성 비교 B<small>공급 ${(near+1).toFixed(1)}㎡ · 거리 540m</small></th><td>4.90억</td><td><b>5.20억</b></td><td>5.50억</td><td>3건</td></tr></tbody></table></div><div class="comparison-bars"><div><span>선택 공고 소계</span><i style="--bar:88%"></i><b>${priceLabel()}</b></div><div><span>비교 A 중위가</span><i class="muted-bar" style="--bar:62%"></i><b>5.15억 원</b></div></div>${note('거래 1건은 최소·중위·최대가 같아요. 적은 표본이나 단순 금액 차이를 대표 시세·보장 수익으로 해석하지 않아요.')}`}<details class="quiet-details"><summary>단지 식별·선정 면적·거래 근거</summary>${facts([['비교 A 식별','합성 식별자 SYN-A · 주소·지역코드 대조 예시'],['사용승인 / 세대수','2015.03.01 / 420세대 · 합성 단지 자료'],['선정 면적',`${near.toFixed(1)}㎡ · 최근접 공급면적만 통계에 사용`],['거래 목록','2026.10.12 · 5.15억 · 8층 · 해제 제외'],['자체 거래','별도 참고 · 주변 후보 수 제외'],['수집 상태','매매 완료 · 분양권 정상 0건 · 입주권 실패']])}${source('합성 실거래·단지 자료 · 2026.11.24')}</details>${btn('replace-candidate','비교 단지 교체안 확인','text-button')}</section><div class="next-action"><div><small>다음으로 살펴볼 것</small><strong>실제로, 납부일에 준비할 수 있을까요?</strong></div>${go('funding','내 자금 확인','primary','wallet')}</div><div class="related-links">${go('legal','법령 근거','quiet-link','book')}${go('commute','출퇴근','quiet-link','pin')}${go('news','지역 뉴스','quiet-link','search')}${go('report','보고서 정리','quiet-link','file')}</div>`;}
function funding(){const f=state.funds,p=state.pdfState==='ready'?currentPrice():null,due=p==null?null:Math.round(p*.1),before=due==null?null:Math.max(0,due-f.cash),received=f.date<='2026-12-10'&&(f.certainty==='확정'||f.include)?f.extra:0,after=due==null?null:Math.max(0,due-f.cash-received);return `<p class="lead">예산 상한과 보유 현금은 달라요.<br>이 분석에 사용할 자금을 따로 알려주세요.</p><section class="surface"><h3>분석별 자금 입력</h3>${state.room==='range'?note('가격 범위를 납부액 하나로 계산하지 않아요. 확인된 호실을 선택해 주세요.','warning'):''}${roomSelect('funding-room','납부를 검토할 호실')}<form id="funding-form">${field('현재 보유 자금 · 확정 입력',`<div class="input-suffix"><input name="cash" type="number" required min="0" max="100000000000" value="${f.cash}"><span>원</span></div>`)}<div class="form-row">${field('추가 자금 · 원',`<input name="extra" type="number" min="0" required value="${f.extra}">`)}${field('유입일',`<input name="date" type="date" required value="${f.date}">`)}${field('입력 상태',`<select name="certainty"><option ${f.certainty==='예상'?'selected':''}>예상</option><option ${f.certainty==='확정'?'selected':''}>확정</option></select>`)}</div><label class="checkbox-line"><input type="checkbox" name="include" ${f.include?'checked':''}> 예상 자금도 포함한 가정 보기</label><div class="actions"><span class="micro">공유 프로필에 저장하지 않아요</span><button class="primary" type="submit">이 분석에 적용</button></div></form></section><section class="surface"><div class="section-title"><h3>계약금 · 2026.12.10</h3>${badge(due==null?'계산 보류':'합성 납부 일정','warning')}</div>${due==null?note('확인된 특정 호실의 필수 옵션·납부 근거가 있어야 계산해요.','warning'):`<div class="funding-total"><small>납부액 · 소계의 10%인 합성 일정</small><strong>${won(due)}</strong></div><div class="metric-grid"><div><small>추가 자금 반영 전 부족액</small><strong>${won(before)}</strong></div><div><small>${f.include&&f.certainty==='예상'?'예상 포함 가정':'확정 입력 기준'} · 반영 후 부족액</small><strong>${won(after)}</strong></div></div><p class="micro">입금일 ${f.date} · ${won(f.extra)} · ${f.certainty}. ${received===0?'납부일 이후 유입 또는 예상 미포함으로 계산에 넣지 않았어요.':f.date==='2026-12-10'?'당일 선후를 몰라 입금 전·후 부족액을 함께 보여줘요.':'납부 전 유입일 기준으로 반영한 예시예요.'}</p><div class="table-scroll"><table><thead><tr><th>납부 항목</th><th>일정·금액</th><th>부족액</th></tr></thead><tbody><tr><th>계약금</th><td>2026.12.10 · ${won(due)}</td><td>입금 전 ${won(before)} / 후 ${won(after)}</td></tr><tr><th>중도금·잔금</th><td>일정·회차 미확인</td><td>계산 보류</td></tr></tbody></table></div>`}${source('합성 납부 일정 · v1 · 9쪽')}${note('확정 표시는 사용자 입력 상태이며 금융기관 검증이 아니에요. 대출·세금을 자동 확정하지 않고 이전 납부의 잔액을 새 자금처럼 중복 사용하지 않아요.')}</section><div class="actions">${go('comparison','비교로 돌아가기')}${go('report','검토 내용 정리','primary','right')}</div>`;}
function evidence(){return `<section class="source-page"><div class="page-label">합성 모집공고 · synthetic-v1 · 7쪽</div><h3>주택형별 공급금액</h3><div class="document-lines"></div><div class="document-highlight">${state.model} · ${state.room==='range'?'확인된 호실 목록':state.room}<br>본체 분양가와 필수 옵션의<br>적용 대상·금액·단위를 원문에서 대조</div><div class="document-lines"></div><small>실제 PDF 원문이 아닌 근거 배치 와이어프레임</small></section><section class="surface"><h3>이 설명과 연결된 근거</h3>${facts([['식별자·회차','선택 공고와 동일 여부 확인'],['공급 / 전용',`${model().supply}㎡ / ${model().private}㎡ · 3쪽`],['가격 / 필수 옵션','호실별 본체·옵션 연결 · 7·8쪽'],['납부 일정','계약금 합성 일정 · 9쪽'],['점검 상태','연결·원문·단위·합계 자동 점검 후 사용']])}${note('추출 성공이나 모델 확신만으로 점검 통과를 대신하지 않아요. 값별 충돌은 해당 판정만 보류하고 독립적인 결과를 유지해요.','warning')}</section><div class="actions">${go('comparison','비교로 돌아가기')}${go('legal','법령 근거도 확인','primary','book')}</div>`;}
function legal(){return `<p class="lead">공고 조건의 관련 근거를 찾고,<br><strong>적용 시점과 추가 확인 사항</strong>을 구분해요.</p><section class="surface">${badge('법령 연결 방식 예시','purple')}<h3>주택공급에 관한 규칙</h3>${facts([['적용 기준','합성 모집공고일 2026.11.20'],['시행 버전','해당 공고일 시행 판본 확인 필요'],['출처','법제처 국가법령정보센터'],['관련 조항','조건 대응 조문·부칙 확인 필요']])}<a class="source-chip" href="https://www.law.go.kr/법령/주택공급에관한규칙" target="_blank" rel="noopener">법령 원문 찾기 ↗</a>${note('법령 조회 입구예요. 공고일 시행 판본·경과규정을 검증한 링크가 아니며 현행 내용을 과거 공고에 자동 적용하지 않아요.','warning')}</section><section class="surface"><h3>아직 확인할 것</h3><ul class="check-list"><li>공고 조건과 조문의 적용 대상</li><li>공고일 당시 시행 버전과 경과규정</li><li>개인별 세대·거주기간 등 요건과 예외</li></ul><p class="micro">개인의 청약 자격을 확정하는 화면이 아니에요.</p></section>${go('report','근거와 남은 확인사항 정리','primary','file')}`;}
function commute(){return `<p class="lead">목적지가 있어야 경로를 살펴볼 수 있어요.<br>경로를 확인하는 동안 다른 분석 결과는 유지해요.</p><section class="surface"><form id="commute-form">${field('도착지',`<input name="destination" required maxlength="120" value="${esc(state.destination)}" placeholder="예: 서울시청 · 정확한 목적지 확인">`)}${field('출발 시각',`<input name="departure" type="datetime-local" required value="${state.departure||'2026-11-25T08:00'}">`)}<button class="primary" type="submit">경로 예시 확인 ${icon('pin')}</button></form></section>${state.routes?`<section class="surface"><div class="section-title"><h3>합성 경로 · ${esc(state.destination)}</h3>${badge('부분 결과','warning')}</div>${facts([['요청 시각',esc(state.departure.replace('T',' '))],['조회 기준','2026.11.24 · 시안 고정 시각']])}<div class="route-card"><h3>대중교통 ${badge('조회 오류','warning')}</h3><p>경로 응답을 확인하지 못했어요.</p><small>ODsay · 연결 도보 시간 미제공 · 0분으로 채우지 않음</small></div><div class="route-card"><h3>자동차 ${badge('합성 예시','purple')}</h3><p><strong>38분 · 14.2km</strong></p><small>카카오모빌리티 연결 영역 예시 · 실제 조회값 아님</small></div>${btn('destination-profile','이 목적지를 공유 프로필 변경안으로','secondary','user')}</section>`:note('목적지 입력 필요 · 대중교통·연결 도보·자동차 결과를 각각 표시해요.')}${go('report','현재 결과로 보고서 보기','quiet-link','file')}`;}
function news(){return `<p class="lead">공고 소재지의 소식을 별도로 확인해요.<br>검색만으로 사실성이나 지역 적합성을 보장하지 않아요.</p><section class="surface"><h3>지역 뉴스 검색</h3>${facts([['검색 조건',regions.find(r=>r.id===notice().region)?.name+' · 최신순'],['제공 형태','제목 · 검색 발췌 · 게시시각 · 원문 링크']])}${btn('news-query','지역 뉴스 예시 열기','primary','search')}${state.newsOpen?`<article class="news-item"><div>${badge('합성 뉴스 항목')}<time>2026.11.24 09:00</time></div><h3>지역 교통·주거 소식이 표시되는 영역</h3><p>제공기관의 제목·검색 발췌가 원래 순서로 놓여요. 실제 기사 제목이나 검색 응답은 아닙니다.</p><span class="micro">원 출처·원문 링크·API 제공 시각은 실제 연결 시 제공</span></article><p class="micro">화면을 벗어나면 목록을 비우고 기사 본문을 임의 수집·요약하지 않아요.</p>`:''}</section>${note('보고서에는 검색 조건·출처·재조회 경로와 누락 사유를 구분해요. 발췌·본문 보관과 PDF 재사용은 이용 권한·D-07 결정 전 확정하지 않아요.')}${go('report','보고서 구성 보기','secondary','file')}`;}
function profile(){const dest=state.proposeDestination;return `<p class="lead">이전 값과 변경 이유를 확인하고<br><strong>다음 대화에 쓸 조건만</strong> 반영하세요.</p><section class="surface"><div class="section-title"><h3>공유 프로필 변경안</h3>${badge(state.profileDecision||'승인 대기',state.profileDecision?'':'warning')}</div><div class="diff-table"><div><span>변경 항목</span><span>현재 · v${state.profileVersion}</span><span>제안 값</span></div>${dest?`<div><b>목적지</b><span>${esc(state.shared.destination)}</span><strong>${esc(state.destination)}</strong></div>`:`<div><b>희망 지역</b><span>${esc(state.shared.region)}</span><strong>${regionNames(state.condition)}</strong></div><div><b>가격 상한</b><span>${money(state.shared.budget)}</span><strong>${money(state.condition.budget)}</strong></div>`}</div><p class="micro">근거: ${dest?'사용자의 목적지 공유 요청':'이번 대화의 탐색 조건'} · 승인 대상 버전 ${state.proposalVersion||state.profileVersion}</p>${!state.profileDecision?`<div class="approval-actions">${btn('profile-cancel','취소','text-button')}${btn('profile-reject','기존 값 유지')}${btn('profile-approve','확인한 변경 반영','primary')}</div>`:note(state.profileDecision==='반영됨'?'공유 프로필 반영 상태 예시예요. 현재 분석과 기존 보고서는 그대로예요.':'변경안을 적용하지 않고 기존 프로필을 유지했어요.')}<p class="micro">미응답·거절·취소는 승인이 아니에요. 상세 자금은 포함하지 않아요.</p></section>${btn('profile-conflict','다른 기기에서 변경된 경우 보기','quiet-link')}${go('report','현재 분석 보기','quiet-link','right')}`;}
function reportData(){const f=state.funds,p=state.pdfState==='ready'?currentPrice():null,due=p===null?null:Math.round(p*.1);return{id:'SYN-SNAPSHOT-01',name:notice().name,model:state.model,room:state.room,price:priceLabel(),supply:model().supply,private:model().private,condition:structuredClone(state.condition),range:state.compareRange,period:`${state.compareStart}–${state.compareEnd}`,funds:{...f},due,before:due===null?null:Math.max(0,due-f.cash),after:due===null?null:Math.max(0,due-f.cash-(f.date<='2026-12-10'&&(f.certainty==='확정'||f.include)?f.extra:0)),destination:state.destination,date:'2026.11.24',selected:state.selected&&!state.comparisonNeedsReview};}
function report(){const d=state.saved||reportData();return `<div class="report-toolbar"><div>${badge(state.saved?'브라우저 메모리에 보관한 시안':'현재 검토 요약','purple')}<p class="micro">${d.id} · 기준 ${d.date}</p></div><div class="button-group">${btn('save-report','요약 보관 시연','secondary','book')}${btn('print-report','인쇄 / PDF로 저장','primary','file')}</div></div><div id="print-report" class="report-document"><header><span class="eyebrow">HOMECIERGE / REVIEW NOTE</span><h2>합성 ${d.name} · ${d.model}</h2><p>${d.room==='range'?'확인된 호실 범위':d.room} · 공급 ${d.supply}㎡ · 전용 ${d.private}㎡</p><strong class="report-price">${d.price}</strong><span class="micro">분양가 + 필수 옵션 · 세금·금융비용 별도</span></header><section><h3>01. 적용한 조건</h3>${conditionSummary(d.condition)}<p>공급면적 ±${d.range}% · ${d.period}</p></section><section><h3>02. 가격 비교</h3><p>${d.selected?'합성 비교 결과 · 매매 A 최소·중위·최대 5.15억 / 1건 (적은 표본). 분양권 정상 0건. 입주권 조회 실패.':'주택형 선택·비교 전 · 비교값 확인 필요'}</p><small>합성 공고 v1 7–8쪽 · 실거래 합성 자료 기준 ${d.date}</small></section><section><h3>03. 자금 준비</h3><p>보유 ${won(d.funds.cash)} · 추가 ${won(d.funds.extra)} (${d.funds.date}, ${d.funds.certainty}) · 예상 포함 ${d.funds.include?'가정 적용':'안 함'}.</p><p>${d.due===null?'특정 호실·확인 납부 근거가 없어 부족액 계산 보류.':`합성 계약금 ${won(d.due)} · 입금 전 ${won(d.before)} / 후 ${won(d.after)} 부족.`}<br>이후 중도금·잔금은 일정 미확인으로 계산 보류.</p></section><section><h3>04. 근거와 생활 조건</h3><p>법령: 공고일 시행 판본·예외·경과규정 추가 확인.<br>경로: ${d.destination?esc(d.destination)+' · 수단별 부분 결과 예시':'목적지 입력 필요'}.<br>뉴스: 소재지 최신순 검색 경로 제공. 기사 재사용 권한 미확정으로 발췌·본문 제외.</p></section><section class="report-pending"><h3>05. 남은 확인사항과 다음 행동</h3><p>미확인 호실 필수 옵션 · 거래 조회 실패 · 적은 표본 · 납부 일정 부족 · 개인 자격 추가 확인.</p><p>미확인 값을 0원·정상 0건으로 채우지 않고 독립 결과를 유지합니다.</p></section><footer>합성 자료 디자인 시안 · ${d.id} · ${d.date} · 구매·자격 판정 아님</footer></div><div class="related-links">${go('legal','법령 원문','quiet-link','book')}${go('commute','출퇴근 조건','quiet-link','pin')}${go('news','뉴스 조회','quiet-link','search')}${go('profile','다음 대화 조건','quiet-link','user')}</div><p class="micro">시안 보관은 이 탭의 메모리에만 유지돼요. 실제 계정 저장·기기 간 복원은 미연결입니다. 브라우저 인쇄에서 “PDF로 저장”을 선택하세요.</p>`;}
function statusView(k){const cfg={loading:['조건에 맞는 공고를 살펴보고 있어요','확인한 조건으로 공고와 주택형을 찾는 중이에요.'],held:['근거를 더 확인해야 해요','공급면적 대응이 미확인인 후보가 있어 가격 비교를 보류했어요.'],empty:['확대 범위에서도 정상 0건이에요','필요한 수집·판별을 마쳤고 결론을 바꿀 미확인 사항이 없는 예시예요.'],error:['거래 자료를 불러오지 못했어요','연결 오류를 정상 0건으로 해석하거나 비교 지역을 확대하지 않아요.']}[k];return `<section class="state-view">${mascot(k,`state-mascot ${k==='loading'?'loading-mascot':''}`)}<h2>${cfg[0]}</h2><p>${cfg[1]}</p>${k==='loading'?`<ol class="loading-steps"><li class="done">구매조건 확인</li><li class="active">공고·주택형 자료 살펴보기 <span class="loading-dots">•••</span></li><li>충족 / 확인 필요 나눠 정리</li></ol>${btn('cancel-loading','지금은 그만할게요','text-button')}`:k==='held'?`${note('같은 동의 정상 0개가 확인되지 않아 구로 자동 확대하지 않아요. 공고·법령·자금 입력은 계속 사용할 수 있어요.','warning')}<div class="actions">${go('evidence','필요한 근거 확인','primary','file')}${go('selected','공고 계속 보기')}</div>`:k==='empty'?`${facts([['우선 지역','같은 법정동 · 전체 거래 종류 정상 0개'],['자동 확대','같은 구로 확대 · 정상 0개'],['구가 없는 경우','같은 읍·면 → 같은 시·군 규칙 적용'],['다음 행동','지역·기간·면적을 자동 변경하지 않음']])}<div class="actions">${btn('edit-comparison','비교 조건 변경안 확인','primary','settings')}${go('report','현재 내용 정리')}</div>`:`${facts([['문제 범위','입주권 거래 조회 · 응답 실패'],['유지할 자료','공고·매매·법령·분석별 자금'],['다음 행동','실패 자료만 다시 조회 · 범위 유지']])}<div class="actions">${btn('retry','다시 시도 예시','primary')}${go('comparison','확인된 결과 보기')}</div>`}</section>`;}
function flow(){return `<p class="lead">각 단계의 예시 화면을 눌러 흐름을 확인하세요.<br>초기 기능 네 단계와 정기 탐색·알림 확장안을 구분했어요.</p><div class="flow-grid">${stages.map((s,i)=>`<section class="flow-card ${s.future?'future':''}"><div class="flow-top"><span class="eyebrow">0${i+1} ${s.en.toUpperCase()}</span>${mascot(s.pose)}</div><h2>${s.name}</h2><p>${s.desc}</p>${badge(s.future?'확장 제안 · 동작하지 않음':'PRD 초기 기능 · 화면 시안',s.future?'':'purple')}<div class="flow-scenes">${s.items.map(v=>btn('preview',views[v][0],'flow-link','right',`data-view="${v}"`)).join('')}</div><details><summary>입력 → 결과 → 다음 행동</summary><p>${['지역·예산 → 확인한 조건 → 확인 후 탐색','조건 → 충족·미확인 후보 → 공고·주택형 선택','선택 주택형·자료 → 통계·부족액·보류 → 근거 보완','결과·근거 → 출처·주의·보고서 → 저장·후속 확인','동의·주기·이벤트 → 검증·중복 확인 → 알림 (미활성)'][i]}</p></details></section>`).join('')}</div><div class="process-note"><strong>공통 확인 원칙</strong><p>같은 회차·호실 가격 + 필수 옵션 / 공급면적 ±5% / 최근접 면적·직선거리 / 고유 주변 최대 5단지 / 거래 종류별 통계 / 자체 거래 별도</p><p>같은 동·읍·면 우선 → 전체 정상 0개일 때만 구 또는 구 없는 시·군 확대. 오류·미확인은 보류해요.</p></div><p class="micro">사용자 제공 2026.11.13 기능설계 구성도 참고 · 최신 PRD v1.2 기준 · 실제 API·Agent 구현 완료를 의미하지 않는 화면 시안입니다.</p>`;}
function alertView(){return `<section class="future-preview"><span class="future-label">05 ALERT · 확장 와이어프레임</span><div class="alert-hero">${mascot('welcome','state-mascot')}<h2>맞는 기회가 생기면, 다시 만나요.</h2><p>정기 탐색·알림의 흐름을 살펴보는 구상 화면이에요.</p></div><section class="surface"><h3>알림 시작 전에 정할 것</h3>${facts([['탐색 조건','사용자가 승인한 공유 프로필'],['알림 대상','조건 충족 · 신규 · 변경 공고'],['흐름','재탐색 → 검증 → 설명 → 중복 확인'],['미정','수신 동의·주기·채널·중복·정정·해지·재시도']])}<button class="primary" disabled>알림 설정 · 확장 기능</button><p class="micro">실제 스케줄러·알림 발송은 활성화하지 않습니다.</p></section><div class="notification-sample">${icon('bell')}<div><strong>조건에 맞는 새로운 공고가 있어요</strong><p>합성 가람 아파트 · 검증 후 도착하는 알림 예시</p><span class="micro">중복·이전 발송 확인 필요 · 실제 알림 아님</span></div></div>${go('results','알림에서 후보로 이동하는 예시','secondary','right')}</section>`;}
function library(){return `<div class="section-title"><p class="lead">이 탭에서 살펴본 검토를 이어가세요.</p>${go('conditions','새 검토','primary','plus')}</div><section class="surface"><div class="saved-row">${icon('chat')}<div><h3>합성 ${notice().name} · ${state.model} 검토</h3><p>현재 선택·자금 유지 · 메모리 예시</p></div>${go('comparison','이어보기')}</div>${state.saved?`<div class="saved-row">${icon('file')}<div><h3>보관한 검토 요약</h3><p>${state.saved.id} · 조건·가격 고정</p></div>${go('report','같은 요약 열기')}</div>`:note('보고서에서 요약 보관을 시연할 수 있어요.')}<div class="actions">${go('report','현재 보고서','text-button')}${btn('delete-analysis','이 분석 삭제 범위','text-button')}</div></section><p class="micro">실제 계정별 다중 대화·결과 저장과 기기 간 복원은 기존 기능과 연결이 필요해요.</p>`;}
function account(){return `<section class="surface"><h3>계정과 자료 관리</h3>${facts([['계정','합성 예시 · 실제 인증 아님'],['공유 프로필','승인한 탐색 조건·목적지'],['분석별 자료','대화·자금·조건·근거 참조'],['삭제','범위·영향 확인 → 요청 → 처리 상태']])}<div class="actions">${btn('delete-analysis','개별 분석 삭제 시안')}${btn('delete-account','계정 삭제 시안','text-button')}</div>${note('이 시안의 삭제는 브라우저 메모리에만 적용돼요. 서버·관련 보고서·백업 처리는 실제 연결·검수가 필요합니다.')}</section>`;}
function body(){return({welcome,login,conditions:()=>`<p class="lead">필수 조건은 <strong>지역과 구매 가격 상한</strong> 두 가지예요.<br>나머지는 정해진 만큼만 더해 주세요.</p><section class="surface">${conditionEditor()}</section>`,results,selected,comparison,funding,evidence,legal,commute,news,profile,report,flow,alert:alertView,library,account,loading:()=>statusView('loading'),held:()=>statusView('held'),empty:()=>statusView('empty'),error:()=>statusView('error')})[state.view]();}
function sidePanel(){if(!state.panel||['welcome','login','flow'].includes(state.view))return '';return `<aside class="context-panel" aria-label="현재 검토 요약"><div class="context-title"><h2>지금 살펴보는 내용</h2>${btn('toggle-panel',icon('close'),'icon-button','','aria-label="요약 패널 닫기"')}</div><div class="context-inner"><div class="context-state">${mascot(['held','error','empty','loading'].includes(state.view)?state.view:state.view==='comparison'?'thinking':state.view==='report'?'complete':'welcome')}<div><strong>${views[state.view][0]}</strong><span>${state.selected?'한 공고 · 한 주택형 검토 중':'조건을 정하고 후보를 찾아요'}</span></div></div><section><span class="eyebrow">APPLIED CONDITIONS</span><h3>적용한 탐색 조건</h3>${conditionSummary()}${go('conditions','이번 검색 조건 수정','text-button','settings')}</section>${state.selected?`<section><span class="eyebrow">SELECTED NOTICE</span><h3>합성 ${notice().name} · ${state.model}</h3><p class="context-price">${priceLabel()}</p><p class="micro">분양가 + 필수 옵션 · 세금 등 별도</p>${facts([['공급면적',`${model().supply}㎡`],['전용면적',`${model().private}㎡`],['호실',state.room==='range'?'확인된 호실 범위':state.room]])}${source()}</section>`:''}<section><h3>연결된 자료</h3>${[['comparison','chart'],['funding','wallet'],['legal','book'],['commute','pin'],['news','search'],['report','file']].map(([v,i])=>go(v,views[v][0],'context-link',i)).join('')}</section><div class="context-help">${icon('shield')}확인하지 못한 정보는<br>다음에 확인할 항목으로 남겨요.</div></div></aside>`;}
function progress(){const step=views[state.view][2];return step?`<nav class="journey" aria-label="구매 검토 단계">${stages.map((s,i)=>`<button data-action="go" data-view="${['conditions','results','comparison','report','alert'][i]}" class="${i+1===step?'current':''} ${s.future?'future':''}" ${i+1===step?'aria-current="step"':''}><span>${i+1<step?'✓':`0${i+1}`}</span><strong>${s.name}</strong>${s.future?'<small>확장</small>':''}</button>`).join('')}</nav>`:'';}
function nav(){return `<aside class="sidebar ${state.mobileNav?'mobile-open':''}"><a class="brand" href="${entryPath}">${mascot('welcome','brand-mascot')}<span>홈시어지<small>HomeCierge</small></span></a>${btn('new','새 대화','new-chat','plus')}<div class="sidebar-label">내 공간</div>${go('library','내 대화·보고서',`nav-link ${state.view==='library'?'active':''}`,'chat')}${go('profile','공유 프로필',`nav-link ${state.view==='profile'?'active':''}`,'user')}${go('alert','기회 알림 <small>확장</small>',`nav-link ${state.view==='alert'?'active':''}`,'bell')}<div class="sidebar-label recent-label">최근 살펴본 예시</div>${btn('preview','<strong>가람 아파트 · 84A</strong><small>가격과 납부 일정 검토</small>','recent-item','','data-view="comparison"')}${btn('preview','<strong>내 조건에 맞는 청약 찾기</strong><small>광진구 · 성동구 / 8억 이내</small>','recent-item','','data-view="results"')}<div class="sidebar-spacer"></div>${go('flow','단계별 화면 목차',`nav-link ${state.view==='flow'?'active':''}`,'flow')}${btn('design-guide','디자인 시스템','nav-link','book')}<a class="nav-link" href="/#home">${icon('home')}기존 연결 기능 ↗</a><div class="sidebar-user">${go(state.auth?'account':'login',`<span class="user-avatar">H</span><span>${state.auth?'내 집 마련 워크스페이스':'나의 첫 집을 위한 공간'}<small>${state.auth?'예시 계정 · 이 탭에서만 유지':'로그인 후 검토를 시작해요'}</small></span>`,'account-button')}</div></aside>`;}
const requests={conditions:'광진구나 성동구에서 8억 이내의 청약을 찾고 있어요.',results:'확인한 조건으로 공고를 찾아주세요.',selected:'이 공고에서 어떤 주택형을 검토할 수 있나요?',comparison:'선택한 주택형을 주변 실거래와 비교해 주세요.',funding:'계약금 납부일에 돈이 얼마나 부족할까요?',evidence:'이 금액과 면적의 근거를 보고 싶어요.',legal:'공고 조건에 관련된 법령도 확인하고 싶어요.',commute:'회사까지 출퇴근하기는 어떨까요?',news:'이 지역의 최근 소식을 확인하고 싶어요.',report:'확인한 내용과 남은 것을 정리해 주세요.',profile:'이 조건을 다음 대화에도 쓰고 싶어요.',held:'왜 지금은 비교를 판단할 수 없나요?',empty:'비교할 거래가 정말 없는 건가요?',error:'일부 자료를 불러오지 못하면 어떻게 하나요?'};
function render(){const previousScroll=root.querySelector('.main-scroll')?.scrollTop||0,sideScroll=root.querySelector('.context-panel')?.scrollTop||0,sameView=state.renderedView===state.view;const v=state.view,home=v==='welcome';root.innerHTML=`<div class="app-shell ${isAurora?'aurora':''} ${home?'is-home':''}">${nav()}<div class="main-shell"><header class="topbar"><div class="breadcrumb">${btn('mobile-nav',icon('panel'),'icon-button mobile-menu','','aria-label="메뉴 열기"')}<span>${home?(isAurora?'AI 청약 탐색':'함께 찾는 내 집'):'내 집 검토'}</span><i>/</i><strong>${views[v][0]}</strong></div><div class="header-tools"><span class="preview-label">합성 데이터 · 디자인 시안</span><select id="view-select" aria-label="시안 단계 선택">${Object.entries(views).map(([k,val])=>`<option value="${k}" ${k===v?'selected':''}>${val[0]}</option>`).join('')}</select>${!['welcome','login','flow'].includes(v)?btn('toggle-panel',icon('panel'),'icon-button','','aria-label="현재 검토 요약 열기"'):''}${!state.auth?go('login','로그인','text-button'):''}</div></header>${progress()}<div class="workspace"><main class="conversation-column" id="conversation" tabindex="-1"><div class="main-scroll"><div class="page-content ${home?'home-content':''} ${v==='flow'?'flow-content':''}">${!['welcome','login'].includes(v)?`<div class="page-heading"><span class="eyebrow">${views[v][2]?`0${views[v][2]} / ${stages[views[v][2]-1].en.toUpperCase()}`:'MY HOMECIERGE'}</span><h1>${views[v][1]}</h1></div>`:''}${!['welcome','login','flow','alert','account','library'].includes(v)?`${requests[v]?`<div class="user-message"><span>나</span><p>${esc(state.userRequests?.[v]||requests[v])}</p></div>`:''}<div class="conversation-intro"><div class="assistant-label">${mascot('welcome')}<strong>홈시어지${isAurora?' AI':''}</strong><span>함께 확인하는 내 집 마련</span></div>${state.history.length?btn('history',`앞선 대화 ${state.history.length}개 ${state.showHistory?'접기':'보기'}`,'history-toggle'):''}</div>${state.showHistory?`<div class="history-trail">${state.history.map(h=>go(h,views[h][0],'history-chip')).join('')}</div>`:''}`:''}${isAurora&&['conditions','results','comparison','funding','evidence','report'].includes(v)?`<div class="ai-reasoning-label"><i aria-hidden="true"></i>${({conditions:'질문을 조건으로 정리해요',results:'조건 충족 여부를 나눠 살펴봐요',comparison:'같은 기준의 근거를 연결해요',funding:'입력한 자금과 납부일을 함께 봐요',evidence:'설명과 원문의 위치를 연결해요',report:'확인한 결과와 다음 행동을 정리해요'})[v]}</div>`:''}${body()}</div></div>${!['login','flow','account'].includes(v)?`<div class="composer-area"><form id="composer" class="composer"><label class="sr-only" for="chat-input">궁금한 내용이나 조건 변경 요청</label><textarea id="chat-input" maxlength="1500" rows="1" placeholder="${home?'예: 광진구나 성동구에서 8억 이내의 청약을 찾고 있어요.':'궁금한 내용이나 바꾸고 싶은 조건을 알려주세요.'}">${esc(state.draft)}</textarea><div class="composer-bottom"><div>${btn('upload',`${icon('plus')} 공고 PDF`,'attach-button')}${state.selected?`<span class="composer-context">${state.model} · ${state.room==='range'?'호실 범위':state.room}</span>`:''}</div><button class="send-button" type="submit" aria-label="메시지 보내기" ${!state.draft.trim()?'disabled':''}>${icon('arrow')}</button></div></form><p class="composer-note">${icon('shield')}합성 화면 시안 · 실제 조회·AI 응답 아님 · 최종 조건은 공식 모집공고에서 확인하세요.</p></div>`:''}${isAurora&&home?auroraFollowup():''}</main>${sidePanel()}</div></div></div>`;document.title=`${views[v][0]} · 홈시어지 시안`;state.renderedView=v;if(sameView){root.querySelector('.main-scroll').scrollTop=previousScroll;if(root.querySelector('.context-panel'))root.querySelector('.context-panel').scrollTop=sideScroll;}}
function openDialog(title,html){const d=document.querySelector('#ui-dialog');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2>${btn('close-dialog','×','icon-button','','aria-label="닫기"')}</div>${html}`;if(!d.open)d.showModal();}
const announce=s=>document.querySelector('#chat-announcement').textContent=s;
function conditionApproval(c){state.pendingCondition=c;openDialog('이 조건으로 찾아볼까요?',`${conditionSummary(c)}${note('이번 분석 조건만 바뀌어요. 공유 프로필과 기존 보고서는 자동으로 바꾸지 않아요.')}<div class="actions">${btn('close-dialog','더 수정할게요')}${btn('apply-condition','확인하고 공고 찾기','primary')}</div>`);}
function compareApproval(){openDialog('비교 조건 변경안',`<form id="compare-form"><div class="form-row">${field('기존 면적 범위',`<input value="±${state.compareRange}%" disabled>`)}${field('변경할 범위 · %',`<input name="range" type="number" min="0.1" max="50" step="any" required value="${state.compareRange}">`)}</div><div class="form-row">${field('계약 시작일',`<input name="start" type="date" required value="${state.compareStart}">`)}${field('종료일',`<input name="end" type="date" required value="${state.compareEnd}">`)}</div><p class="micro">지역은 유지하고 확인한 변경만 새 검토에 적용해요.</p><p class="form-error" id="compare-error" role="alert"></p><button class="primary" type="submit">변경안 확인하기</button></form>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='new'){clearTimeout(state.timer);state.funds={cash:0,extra:0,date:'2026-12-10',certainty:'예상',include:false};state.condition={...initialCondition(),regions:regions.filter(r=>state.shared.region.includes(r.name)).map(r=>r.id),budget:state.shared.budget};state.room='range';state.selected=false;state.noticeId='A';state.model='84A';state.history=[];state.userRequests={};state.destination=state.shared.destination==='미등록'?'':state.shared.destination;state.routes=false;state.comparisonNeedsReview=false;state.mobileNav=false;state.view='welcome';return render();}
 if(a==='prompt'){state.draft=b.dataset.prompt;render();const input=root.querySelector('#chat-input');input.focus();input.setSelectionRange(input.value.length,input.value.length);return;}
 if(a==='go'){state.mobileNav=false;if(b.dataset.view==='profile'){state.proposeDestination=false;state.profileDecision=null;state.proposalVersion=state.profileVersion;}return setView(b.dataset.view);}
 if(a==='preview'){state.auth=true;state.selected=['comparison','funding','report','held','empty','error','evidence','legal','commute','news'].includes(b.dataset.view);return setView(b.dataset.view);}
 if(a==='demo-login'){state.auth=true;return setView(state.afterLogin||'conditions');}
 if(a==='mobile-nav'){state.mobileNav=!state.mobileNav;return render();}
 if(a==='toggle-panel'){state.panel=!state.panel;return render();}
 if(a==='history'){state.showHistory=!state.showHistory;return render();}
 if(a==='close-dialog')return document.querySelector('#ui-dialog').close();
 if(a==='source')return setView('evidence');
 if(a==='design-guide')return openDialog('홈시어지 · Periwinkle',`<div class="palette"><div style="--color:#6576f5">캐릭터<br>#6576F5</div><div style="--color:#4654cb">주요 행동<br>#4654CB</div><div style="--color:#eef0ff">선택 배경<br>#EEF0FF</div><div style="--color:#242534">본문<br>#242534</div></div><p>브랜드 컬러는 캐릭터와 선택 상태에, 진한 블루는 버튼과 읽어야 할 강조에 사용해요.</p><div class="mascot-lineup">${Object.keys(poses).map(p=>mascot(p)).join('')}</div>${note('시작 144–176px / 상태 안내 154–176px / 자료 패널 60px. 금액·면적·출처와 주요 행동보다 캐릭터가 앞서지 않게 배치해요.')}<p class="micro">Pretendard · 제목 27px / 대화 15px / 설명 12px · 8px 간격 기준 · 모션 감소 설정 지원</p>`);
 if(a==='select-notice'){state.noticeId=b.dataset.id;state.model=Object.keys(notice().models)[0];state.room='range';state.selected=false;state.pdfState='ready';return setView('selected');}
 if(a==='model'){state.model=b.dataset.model;state.room='range';state.selected=false;return render();}
 if(a==='start-compare'){state.selected=true;if(state.pdfState!=='ready'||!prices().length||(state.room!=='range'&&currentPrice()===null))return setView('held');state.comparisonNeedsReview=false;state.loadingNext='comparison';return setView('loading');}
 if(a==='trade'){state.trade=b.dataset.trade;return render();}
 if(a==='apply-condition'){state.condition=state.pendingCondition;state.pendingCondition=null;state.selected=false;document.querySelector('#ui-dialog').close();state.loadingNext='results';return setView('loading');}
 if(a==='edit-comparison')return compareApproval();
 if(a==='apply-comparison'){state.compareRange=state.pendingCompare.range;state.compareStart=state.pendingCompare.start;state.compareEnd=state.pendingCompare.end;state.comparisonNeedsReview=true;document.querySelector('#ui-dialog').close();return setView('comparison');}
 if(a==='replace-candidate')return openDialog('비교 단지 교체안',`${facts([['이전','합성 비교 B · 현재 지역'],['변경안','합성 비교 C · 같은 지역·면적·기간 검증 위치'],['공통 제한','추가가 아닌 교체 · 고유 주변 최대 5단지']])}${note('승인 구조 시안입니다. 실제 단지 적합성·식별 조회는 실행하지 않아요.')}<div class="actions">${btn('close-dialog','취소')}${btn('replace-confirm','교체 요청 시연','primary')}</div>`);
 if(a==='replace-confirm')return openDialog('교체 요청 시안',note('단지 식별·지역·면적·기간을 검증한 뒤 교체할 위치예요. 현재 합성 통계는 바뀌지 않았어요.'));
 if(a==='cancel-loading'){clearTimeout(state.timer);return setView('conditions');}
 if(a==='retry'){state.loadingNext='comparison';return setView('loading');}
 if(a==='upload'){if(!state.auth)return setView('login');return openDialog('공고 PDF 보완',`<p>같은 공고·회차 PDF를 자동 확보하고 실패 시 파일로 보완해요.</p><label class="file-drop">PDF 선택<input type="file" id="pdf-file" accept="application/pdf,.pdf"></label><p id="file-status" class="micro" role="status">서버로 보내지 않아요. 선택만으로 문서 점검이 완료되지 않습니다.</p>`);}
 if(a==='news-query'){state.newsOpen=true;return render();}
 if(a==='destination-profile'){state.proposeDestination=true;state.proposalVersion=state.profileVersion;state.profileDecision=null;return setView('profile');}
 if(a==='profile-cancel'||a==='profile-reject'){state.profileDecision=a==='profile-cancel'?'취소됨':'유지됨';return render();}
 if(a==='profile-approve'){if(state.proposalVersion&&state.proposalVersion!==state.profileVersion)return openDialog('변경된 프로필을 다시 확인해 주세요',note('다른 기기에서 버전이 바뀌어 반영을 막았어요. 최신 값으로 다시 대조해 주세요.','warning'));if(state.proposeDestination)state.shared.destination=state.destination;else{state.shared.region=regionNames(state.condition);state.shared.budget=state.condition.budget;}state.profileVersion++;state.profileDecision='반영됨';return render();}
 if(a==='profile-conflict'){state.proposalVersion=state.profileVersion;state.profileVersion++;state.profileDecision=null;render();return openDialog('다른 기기에서 조건이 변경됐어요',`${note('현재 버전과 제안의 기준 버전이 달라 반영을 막아요.','warning')}${btn('profile-refresh','최신 버전으로 변경안 다시 보기','primary')}`);}
 if(a==='profile-refresh'){state.proposalVersion=state.profileVersion;document.querySelector('#ui-dialog').close();return render();}
 if(a==='save-report'){if(!state.saved)state.saved=reportData();announce('이 탭의 메모리에 같은 요약을 보관했어요.');return render();}
 if(a==='print-report')return window.print();
 if(a==='delete-analysis'||a==='delete-account'){state.deleteScope=a;return openDialog(a==='delete-account'?'계정 삭제 범위 확인':'개별 분석 삭제 범위 확인',`<p>${a==='delete-account'?'예시 계정의 대화·공유 프로필·자금·보관 요약':'이 분석의 대화·자금·선택 조건·보관 요약'}을 이 탭의 메모리에서 지워요.</p>${note('외부 원문·서버·백업은 삭제하지 않는 시안이에요. 실제 삭제는 관련 자료의 영향·처리 상태 연결이 필요해요.')}<div class="actions">${btn('close-dialog','취소')}${btn('delete-confirm','예시 자료 삭제','danger-button')}</div>`);}
 if(a==='delete-confirm'){clearTimeout(state.timer);state.saved=null;state.history=[];state.userRequests={};state.selected=false;state.destination='';state.routes=false;state.funds={cash:0,extra:0,date:'2026-12-10',certainty:'예상',include:false};state.condition={...initialCondition(),regions:[],budget:0};state.profileDecision=null;state.proposeDestination=false;if(state.deleteScope==='delete-account'){state.auth=false;state.shared={region:'미등록',budget:0,destination:'미등록'};}document.querySelector('#ui-dialog').close();setView('welcome');state.history=[];return openDialog('예시 자료 삭제 완료',note('삭제한 입력을 다음 분석의 기본값으로 재사용하지 않아요.'));}
});
document.addEventListener('change',e=>{if(e.target.id==='view-select'){state.auth=!['welcome','login','flow','alert'].includes(e.target.value);state.selected=['comparison','funding','report','held','empty','error','evidence','legal','commute','news'].includes(e.target.value);setView(e.target.value,{allow:true});}if(['room-select','funding-room'].includes(e.target.id)){state.room=e.target.value;render();}if(e.target.id==='pdf-state'){state.pdfState=e.target.value;render();}if(e.target.id==='pdf-file'){const f=e.target.files[0];document.querySelector('#file-status').textContent=f?`${f.name} · 선택만 확인했어요. 판독·전송·검증은 실행하지 않습니다.`:'파일을 선택하지 않았어요.';}});
document.addEventListener('input',e=>{if(e.target.id==='chat-input'){state.draft=e.target.value;root.querySelector('.send-button').disabled=!state.draft.trim();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(state.mobileNav||state.panel)){state.mobileNav=false;state.panel=false;render();}if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();root.querySelector('#composer').requestSubmit();}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,fd=new FormData(f);
 if(f.id==='condition-form'){const c={regions:fd.getAll('region'),budget:Number(fd.get('budget')),areaMin:fd.get('areaMin')||'',areaMax:fd.get('areaMax')||'',unit:fd.get('unit'),moveStart:fd.get('moveStart')||'',moveEnd:fd.get('moveEnd')||'',closed:fd.has('closed')};let error='';if(!c.regions.length)error='희망 지역을 한 곳 이상 선택해 주세요.';else if(!Number.isSafeInteger(c.budget)||c.budget<=0)error='예산을 양수의 원 단위 정수로 입력해 주세요.';else if(c.areaMin&&c.areaMax&&Number(c.areaMin)>Number(c.areaMax))error='공급면적 최소값이 최대값보다 커요.';else if(c.moveStart&&c.moveEnd&&c.moveStart>c.moveEnd)error='입주 시작월이 종료월보다 늦어요.';if(error){document.querySelector('#condition-error').textContent=error;return;}return conditionApproval(c);}
 if(f.id==='funding-form'){state.funds={cash:Number(fd.get('cash')),extra:Number(fd.get('extra')),date:fd.get('date'),certainty:fd.get('certainty'),include:fd.has('include')};announce('이 분석의 자금 입력만 적용했어요.');return render();}
 if(f.id==='commute-form'){state.destination=String(fd.get('destination')).trim();state.departure=fd.get('departure');state.routes=!!state.destination;return render();}
 if(f.id==='compare-form'){const c={range:Number(fd.get('range')),start:fd.get('start'),end:fd.get('end')};if(c.start>c.end){document.querySelector('#compare-error').textContent='계약 시작일이 종료일보다 늦어요.';return;}state.pendingCompare=c;return openDialog('변경 전후를 확인해 주세요',`${facts([['공급면적',`±${state.compareRange}% → ±${c.range}%`],['계약일',`${state.compareStart}–${state.compareEnd}<br>→ ${c.start}–${c.end}`],['유지','공고·주택형·지역·거래 종류']])}<div class="actions">${btn('close-dialog','취소')}${btn('apply-comparison','이 변경만 적용','primary')}</div>`);}
 if(f.id==='composer'){const text=state.draft.trim();if(!text)return;if(!state.auth)return setView('login');let v='conditions';if(/프로필/.test(text)){state.profileDecision=null;state.proposeDestination=false;state.proposalVersion=state.profileVersion;v='profile';}else if(/법령|자격|조문/.test(text))v='legal';else if(/출퇴근|목적지|경로/.test(text))v='commute';else if(/뉴스|소식/.test(text))v='news';else if(/자금|납부|계약금|잔금|부족/.test(text))v='funding';else if(/근거|원문|출처/.test(text))v='evidence';else if(/보고서|정리|요약/.test(text))v='report';else if(/비교|실거래|시세/.test(text))v='comparison';else if(/공고.*검토|주택형/.test(text))v='selected';if(v==='conditions'){const r=regions.filter(r=>text.includes(r.name.slice(-3))).map(r=>r.id),amount=text.match(/([1-9]\d*(?:\.\d+)?)\s*억/);const c={...state.condition,regions:r.length?r:state.condition.regions,budget:amount?Math.round(Number(amount[1])*1e8):state.condition.budget};if(c.regions.length&&c.budget>0)return conditionApproval(c);}state.userRequests={...state.userRequests,[v]:text};setView(v);announce('키워드로 연결한 화면 예시입니다. 실제 AI 해석을 실행하지 않았어요.');}
});
